## Code Example

```javascript
// Example: basic WebSocket stream ordering test (conceptual)
const WebSocket = require('ws');
const ws = new WebSocket('wss://example.com/stream');
let lastSeq = -1;
let ok = true;
let count = 0;
ws.on('message', (data) => {
  const msg = JSON.parse(data);
  if (typeof msg.seq !== 'number' || msg.seq <= lastSeq) ok = false;
  lastSeq = msg.seq;
  count++;
  if (count >= 100) ws.close();
});
```

